package checks;
import com.raiiiden.warborn.hybrid.*;import java.util.*;import java.util.function.*;import com.mojang.blaze3d.vertex.*;import net.minecraft.client.renderer.*;
public final class HybridChecks {
 static int n;static void ok(boolean b){n++;if(!b)throw new AssertionError("hybrid check "+n);}
 public static class Register{public String id;public Supplier<Object> supplier;public Holder register(String id,Supplier<Object>s){this.id=id;supplier=s;return new Holder();}}public static class Holder{public Object get(){return "new goggles";}}public static class Creative{public Object item;public void accept(Object o){item=o;}}
 public static class Consumer implements VertexConsumer{public int r,g,b,a,u,v,light;public VertexConsumer addVertex(float x,float y,float z){return this;}public VertexConsumer setColor(int r,int g,int b,int a){this.r=r;this.g=g;this.b=b;this.a=a;return this;}public VertexConsumer setUv(float u,float v){return this;}public VertexConsumer setUv1(int u,int v){this.u=u;this.v=v;return this;}public VertexConsumer setUv2(int u,int v){light=u;return this;}public VertexConsumer setNormal(float x,float y,float z){return this;}}
 public static class Source implements MultiBufferSource{public Consumer consumer=new Consumer();public RenderType type;public VertexConsumer getBuffer(RenderType r){type=r;return consumer;}}
 public static void main(String[]args){Register reg=new Register();Hybrid6.register(reg);ok(reg.id.equals("hybrid_thermal_goggles"));Creative tab=new Creative();Hybrid6.creative(tab);ok(tab.item.equals("new goggles"));ok(Hybrid6.extend(Set.of("thermal"),Hybrid6.MODE).containsAll(Set.of("thermal",Hybrid6.MODE)));Map<String,Integer> rates=new HashMap<>();Hybrid6.drain(rates);ok(rates.get(Hybrid6.MODE)==5);
 Source source=new Source();MultiBufferSource wrapper=(MultiBufferSource)HybridClient6.buffers(source);ok(HybridClient6.buffers(wrapper)==wrapper);RenderType ordinary=new RenderType(DefaultVertexFormat.NEW_ENTITY);VertexConsumer vc=wrapper.getBuffer(ordinary);ok(vc!=source.consumer&&source.type!=ordinary);ok(vc.setColor(10,20,30,190)==vc);ok(source.consumer.r==239&&source.consumer.g==1&&source.consumer.b==137&&source.consumer.a==190);vc.setUv1(12,0).setUv2(0,0);ok(source.consumer.u==0&&source.consumer.v==10&&source.consumer.light==240);ok(wrapper.getBuffer(ordinary)==vc);RenderType text=new RenderType(new Object());ok(wrapper.getBuffer(text)==source.consumer&&source.type==text);ok(vc.addVertex(1,2,3).setNormal(1,0,0)==vc);vc.addVertex(1,2,3,0xff12ff34,.1f,.2f,0,0,0,1,0);ok(source.consumer.r==239&&source.consumer.g==1&&source.consumer.b==137&&source.consumer.u==0&&source.consumer.v==10&&source.consumer.light==240);vc.setColor(0x7fabcdef);ok(source.consumer.r==239&&source.consumer.a==127);vc.addVertex(new PoseStack.Pose(),1,2,3).setColor(22,33,44,255);ok(source.consumer.r==239);System.out.println("HYBRID_REGISTRATION_MESH_BUFFER_CHECKS="+n);}
}
